+.qty-btn:hover { background: var(--border); }
+.qty-val { font-size: .9rem; font-weight: 700; min-width: 20px; text-align: center; }
+.cart-footer { padding: 20px 24px; border-top: 1px solid var(--border); }
+.cart-subtotal { display: flex; justify-content: space-between; font-size: 1rem; font-weight: 700; margin-bottom: 16px; }
+.btn-checkout { width: 100%; padding: 15px; background: var(--accent); color: #fff; border-radius: var(--radius-sm); font-weight: 800; font-size: 1rem; letter-spacing: .02em; transition: background var(--transition); }
+.btn-checkout:hover { background: #cf3550; }
+.cart-empty { text-align: center; padding: 48px 24px; color: var(--muted); }
+.cart-empty svg { width: 48px; height: 48px; margin: 0 auto 16px; opacity: .3; }
+
