", direction=None, fact=None, file_name='/workspace/sandbox/control/shopping-home-page--framework-vanilla-js--style-modern/claude-sonnet-4.6__s3/styles.css', full_command_text=None, hook_message=None, intention='Create file', new_file_contents="/* ── Reset & Base ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --brand:      #1a1a2e;
  --accent:     #e94560;
  --accent-2:   #f5a623;
  --bg:         #f8f8f6;
  --surface:    #ffffff;
  --text:       #1a1a2e;
  --muted:      #6b7280;
  --border:     #e5e7eb;
  --radius:     12px;
  --radius-sm:  6px;
  --shadow-sm:  0 1px 3px rgba(0,0,0,.08);
  --shadow-md:  0 4px 16px rgba(0,0,0,.1);
  --shadow-lg:  0 16px 40px rgba(0,0,0,.14);
  --font:       'Inter', system-ui, -apple-system, sans-serif;
  --transition: .22s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; }
body { font-family: var(--font); background: var(--bg); color: var(--text); line-height: 1.6; -webkit-font-smoothing: antialiased; }
img  { display: block; max-width: 100%; }
a    { color: inherit; text-decoration: none; }
ul   { list-style: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }

/* ── Utilities ── */
.container { width: min(1240px, 100%); margin-inline: auto; padding-inline: 24px; }
.section-label { font-size: .72rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--accent); margin-bottom: 8px; }
.section-title  { font-size: clamp(1.6rem, 3vw, 2.2rem); font-weight: 800; line-height: 1.2; color: var(--brand); }
.section-header { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin-bottom: 32px; }
.section-header .view-all { font-size: .85rem; font-weight: 600; color: var(--accent); display: flex; align-items: center; gap: 4px; white-space: nowrap; transition: gap var(--transition); }
.section-header .view-all:hover { gap: 8px; }
.badge { display: inline-flex; align-items: center; padding: 3px 10px; border-radius: 99px; font-size: .72rem; font-weight: 700; letter-spacing: .04em; }
.badge-sale { background: var(--accent); color: #fff; }
.badge-new  { background: #10b981; color: #fff; }
.badge-hot  { background: var(--accent-2); color: #fff; }

/* ── Announcement Bar ── */
.announcement-bar { background: var(--brand); color: #fff; font-size: .8rem; font-weight: 500; text-align: center; padding: 9px 24px; letter-spacing: .03em; }
.announcement-bar span { color: var(--accent-2); font-weight: 700; }

/* ── Navbar ── */
.navbar { position: sticky; top: 0; z-index: 100; background: rgba(255,255,255,.92); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border); }
.navbar-inner { display: flex; align-items: center; gap: 32px; height: 64px; }
.logo { font-size: 1.35rem; font-weight: 900; color: var(--brand); letter-spacing: -.02em; flex-shrink: 0; }
.logo span { color: var(--accent); }
.nav-links { display: flex; gap: 28px; flex: 1; }
.nav-links a { font-size: .9rem; font-weight: 500; color: var(--muted); transition: color var(--transition); position: relative; }
.nav-links a::after { content:''; position:absolute; bottom:-4px; left:0; width:0; height:2px; background:var(--accent); transition: width var(--transition); }
.nav-links a:hover, .nav-links a.active { color: var(--text); }
.nav-links a:hover::after, .nav-links a.active::after { width: 100%; }
.nav-actions { display: flex; align-items: center; gap: 4px; margin-left: auto; }
.nav-btn { display: flex; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: var(--radius-sm); color: var(--text); transition: background var(--transition); position: relative; }
.nav-btn:hover { background: var(--bg); }
.nav-btn svg { width: 20px; height: 20px; }
.cart-count { position: absolute; top: 5px; right: 5px; background: var(--accent); color: #fff; font-size: .6rem; font-weight: 700; width: 16px; height: 16px; border-radius: 50%; display: flex; align-items: center; justify-content: center; }
.search-bar { display: flex; align-items: center; background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius-sm); overflow: hidden; flex: 1; max-width: 280px; }
.search-bar input { flex: 1; padding: 8px 12px; font-size: .87rem; border: none; background: transparent; outline: none; color: var(--text); }
.search-bar input::placeholder { color: var(--muted); }
.search-bar button { padding: 8px 12px; color: var(--muted); display: flex; }
.hamburger { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.hamburger span { width: 22px; height: 2px; background: var(--text); border-radius: 2px; transition: var(--transition); }

/* ── Hero ── */
.hero { background: var(--brand); color: #fff; padding: 80px 0 0; overflow: hidden; position: relative; }
.hero::before { content:''; position:absolute; inset:0; background: radial-gradient(ellipse 70% 80% at 70% 50%, rgba(233,69,96,.22), transparent); pointer-events:none; }
.hero-inner { display: grid; grid-template-columns: 1fr 1fr; align-items: center; gap: 48px; position: relative; z-index: 1; }
.hero-eyebrow { font-size: .75rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--accent-2); margin-bottom: 16px; }
.hero h1 { font-size: clamp(2.2rem, 5vw, 3.8rem); font-weight: 900; line-height: 1.08; letter-spacing: -.03em; margin-bottom: 20px; }
.hero h1 em { color: var(--accent); font-style: normal; }
.hero p { font-size: 1.05rem; color: rgba(255,255,255,.72); max-width: 420px; margin-bottom: 36px; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.btn { display: inline-flex; align-items: center; gap: 8px; padding: 13px 26px; border-radius: var(--radius-sm); font-size: .9rem; font-weight: 700; letter-spacing: .01em; transition: all var(--transition); }
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover { background: #cf3550; transform: translateY(-1px); box-shadow: 0 6px 20px rgba(233,69,96,.4); }
.btn-outline { background: transparent; color: #fff; border: 1.5px solid rgba(255,255,255,.3); }
.btn-outline:hover { background: rgba(255,255,255,.08); border-color: rgba(255,255,255,.6); }
.hero-visual { position: relative; padding-top: 40px; align-self: end; }
.hero-img-wrap { border-radius: var(--radius) var(--radius) 0 0; overflow: hidden; height: 440px; background: linear-gradient(135deg,#2a2a4a,#1a1a2e); display: flex; align-items: center; justify-content: center; }
.hero-img-wrap img { width: 100%; height: 100%; object-fit: cover; }
.hero-badge { position: absolute; top: 20px; right: -10px; background: var(--accent-2); color: var(--brand); padding: 10px 16px; border-radius: var(--radius-sm); font-size: .82rem; font-weight: 800; box-shadow: var(--shadow-md); }
.hero-stats { display: flex; gap: 32px; margin-top: 40px; padding-top: 28px; border-top: 1px solid rgba(255,255,255,.1); }
.hero-stat strong { display: block; font-size: 1.6rem; font-weight: 900; line-height: 1; }
.hero-stat span { font-size: .8rem; color: rgba(255,255,255,.55); }

/* ── Category Pills ── */
.categories { padding: 36px 0; background: var(--surface); border-bottom: 1px solid var(--border); }
.cat-list { display: flex; gap: 10px; overflow-x: auto; padding-bottom: 4px; scrollbar-width: none; }
.cat-list::-webkit-scrollbar { display: none; }
.cat-pill { display: flex; align-items: center; gap: 8px; padding: 10px 18px; border-radius: 99px; border: 1.5px solid var(--border); background: var(--bg); font-size: .85rem; font-weight: 600; white-space: nowrap; transition: all var(--transition); cursor: pointer; flex-shrink: 0; }
.cat-pill:hover, .cat-pill.active { background: var(--brand); color: #fff; border-color: var(--brand); }
.cat-pill .cat-icon { font-size: 1.1rem; line-height: 1; }

/* ── Featured Products ── */
.featured-products { padding: 72px 0; }
.products-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.product-card { background: var(--surface); border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow-sm); transition: all var(--transition); display: flex; flex-direction: column; }
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.product-img { position: relative; aspect-ratio: 3/4; background: linear-gradient(135deg, #f0f0f8, #e8e8f0); overflow: hidden; }
.product-img img { width: 100%; height: 100%; object-fit: cover; transition: transform .4s ease; }
.product-card:hover .product-img img { transform: scale(1.06); }
.product-badges { position: absolute; top: 12px; left: 12px; display: flex; flex-direction: column; gap: 4px; }
.product-actions { position: absolute; right: 12px; bottom: 12px; display: flex; flex-direction: column; gap: 6px; opacity: 0; transform: translateX(8px); transition: all var(--transition); }
.product-card:hover .product-actions { opacity: 1; transform: translateX(0); }
.product-action-btn { width: 36px; height: 36px; border-radius: var(--radius-sm); background: rgba(255,255,255,.95); display: flex; align-items: center; justify-content: center; box-shadow: var(--shadow-sm); transition: all var(--transition); }
.product-action-btn:hover { background: var(--accent); color: #fff; }
.product-action-btn svg { width: 16px; height: 16px; }
.product-info { padding: 16px; flex: 1; display: flex; flex-direction: column; }
.product-brand { font-size: .72rem; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); margin-bottom: 4px; }
.product-name { font-size: .95rem; font-weight: 600; color: var(--text); margin-bottom: 8px; line-height: 1.35; flex: 1; }
.product-rating { display: flex; align-items: center; gap: 5px; margin-bottom: 10px; }
.stars { color: var(--accent-2); font-size: .8rem; letter-spacing: 1px; }
.rating-count { font-size: .75rem; color: var(--muted); }
.product-footer { display: flex; align-items: center; justify-content: space-between; margin-top: auto; }
.product-price { display: flex; align-items: baseline; gap: 6px; }
.price-current { font-size: 1.1rem; font-weight: 800; color: var(--text); }
.price-original { font-size: .85rem; color: var(--muted); text-decoration: line-through; }
.add-to-cart { display: flex; align-items: center; justify-content: center; width: 34px; height: 34px; border-radius: var(--radius-sm); background: var(--brand); color: #fff; transition: background var(--transition); }
.add-to-cart:hover { background: var(--accent); }
.add-to-cart svg { width: 16px; height: 16px; }

/* ── Deals Banner ── */
.deals { padding: 72px 0; background: linear-gradient(135deg, var(--brand) 0%, #16213e 100%); }
.deals .section-title { color: #fff; }
.deals .section-label { color: var(--accent-2); }
.deals-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-top: 32px; }
.deal-card { position: relative; border-radius: var(--radius); overflow: hidden; background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.1); padding: 32px; display: flex; flex-direction: column; gap: 16px; transition: all var(--transition); }
.deal-card:hover { background: rgba(255,255,255,.1); transform: translateY(-2px); }
.deal-card.deal-large { grid-row: span 2; padding: 40px; justify-content: flex-end; }
.deal-card-bg { position: absolute; inset: 0; background-size: cover; background-position: center; opacity: .25; }
.deal-eyebrow { font-size: .7rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--accent-2); }
.deal-title { font-size: 1.4rem; font-weight: 800; color: #fff; line-height: 1.25; position: relative; z-index: 1; }
.deal-card.deal-large .deal-title { font-size: clamp(1.6rem, 2.5vw, 2.2rem); }
.deal-desc { font-size: .87rem; color: rgba(255,255,255,.65); position: relative; z-index: 1; }
.deal-cta { align-self: flex-start; padding: 10px 20px; background: var(--accent); color: #fff; border-radius: var(--radius-sm); font-size: .85rem; font-weight: 700; transition: all var(--transition); position: relative; z-index: 1; }
.deal-cta:hover { background: #cf3550; }
.countdown { display: flex; gap: 10px; position: relative; z-index: 1; }
.countdown-unit { text-align: center; background: rgba(255,255,255,.12); border-radius: var(--radius-sm); padding: 8px 12px; min-width: 52px; }
.countdown-num { display: block; font-size: 1.5rem; font-weight: 900; color: #fff; line-height: 1; }
.countdown-label { display: block; font-size: .6rem; text-transform: uppercase; letter-spacing: .08em; color: rgba(255,255,255,.55); margin-top: 2px; }
.deals-grid-right { display: grid; grid-template-rows: 1fr 1fr; gap: 20px; }

/* ── Deals strip ── */
.deals-strip { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }

/* ── Trending / Carousel ── */
.trending { padding: 72px 0; }
.carousel-wrap { position: relative; }
.carousel { display: flex; gap: 20px; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; padding-bottom: 4px; }
.carousel::-webkit-scrollbar { display: none; }
.carousel .product-card { flex: 0 0 calc(25% - 15px); scroll-snap-align: start; }
.carousel-btns { display: flex; gap: 8px; margin-top: 20px; justify-content: flex-end; }
.carousel-btn { width: 40px; height: 40px; border-radius: 50%; border: 1.5px solid var(--border); display: flex; align-items: center; justify-content: center; background: var(--surface); transition: all var(--transition); }
.carousel-btn:hover { background: var(--brand); color: #fff; border-color: var(--brand); }
.carousel-btn svg { width: 18px; height: 18px; }

/* ── Editorial ── */
.editorial { padding: 72px 0; background: var(--surface); }
.editorial-grid { display: grid; grid-template-columns: 1.4fr 1fr; gap: 24px; }
.editorial-card { border-radius: var(--radius); overflow: hidden; background: var(--bg); display: flex; flex-direction: column; transition: box-shadow var(--transition); }
.editorial-card:hover { box-shadow: var(--shadow-lg); }
.editorial-img { aspect-ratio: 16/10; overflow: hidden; background: linear-gradient(135deg, #e8e8f8, #d0d0e8); }
.editorial-img img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
.editorial-card:hover .editorial-img img { transform: scale(1.04); }
.editorial-body { padding: 24px; flex: 1; display: flex; flex-direction: column; }
.editorial-tag { display: inline-block; font-size: .7rem; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: var(--accent); margin-bottom: 10px; }
.editorial-title { font-size: 1.2rem; font-weight: 800; line-height: 1.3; margin-bottom: 8px; color: var(--text); }
.editorial-card.editorial-main .editorial-title { font-size: 1.5rem; }
.editorial-excerpt { font-size: .88rem; color: var(--muted); line-height: 1.65; flex: 1; margin-bottom: 16px; }
.editorial-meta { display: flex; align-items: center; justify-content: space-between; font-size: .78rem; color: var(--muted); }
.editorial-author { display: flex; align-items: center; gap: 8px; font-weight: 600; color: var(--text); }
.author-avatar { width: 28px; height: 28px; border-radius: 50%; background: linear-gradient(135deg, var(--accent), var(--accent-2)); display: flex; align-items: center; justify-content: center; font-size: .7rem; font-weight: 800; color: #fff; }
.editorial-sub-grid { display: flex; flex-direction: column; gap: 24px; }
.editorial-card.editorial-sm .editorial-img { aspect-ratio: 16/7; }

/* ── Brands ── */
.brands { padding: 56px 0; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.brands-label { text-align: center; font-size: .75rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); margin-bottom: 28px; }
.brands-list { display: flex; align-items: center; justify-content: center; gap: 48px; flex-wrap: wrap; }
.brand-logo { font-size: 1.25rem; font-weight: 900; letter-spacing: -.04em; color: var(--border); transition: color var(--transition); cursor: default; }
.brand-logo:hover { color: var(--muted); }

/* ── Newsletter ── */
.newsletter { padding: 80px 0; background: var(--bg); }
.newsletter-inner { background: var(--brand); border-radius: 20px; padding: 56px 64px; display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
.newsletter-text .section-label { color: var(--accent-2); }
.newsletter-text .section-title { color: #fff; margin-top: 6px; }
.newsletter-text p { color: rgba(255,255,255,.65); font-size: .95rem; margin-top: 12px; }
.newsletter-form { display: flex; flex-direction: column; gap: 12px; }
.input-row { display: flex; gap: 10px; }
.input-row input { flex: 1; padding: 13px 16px; border-radius: var(--radius-sm); border: 1.5px solid rgba(255,255,255,.15); background: rgba(255,255,255,.08); color: #fff; font-size: .9rem; outline: none; transition: border-color var(--transition); }
.input-row input::placeholder { color: rgba(255,255,255,.4); }
.input-row input:focus { border-color: var(--accent); }
.input-row .btn-primary { flex-shrink: 0; }
.newsletter-note { font-size: .75rem; color: rgba(255,255,255,.4); }
.newsletter-note a { color: rgba(255,255,255,.6); text-decoration: underline; }

/* ── Footer ── */
.footer { background: var(--brand); color: rgba(255,255,255,.7); padding: 56px 0 32px; }
.footer-grid { display: grid; grid-template-columns: 1.4fr repeat(3, 1fr); gap: 40px; margin-bottom: 48px; }
.footer-brand .logo { font-size: 1.3rem; margin-bottom: 12px; display: block; color: #fff; }
.footer-brand p { font-size: .87rem; line-height: 1.7; max-width: 240px; }
.footer-social { display: flex; gap: 8px; margin-top: 20px; }
.social-btn { width: 36px; height: 36px; border-radius: var(--radius-sm); background: rgba(255,255,255,.07); display: flex; align-items: center; justify-content: center; transition: background var(--transition); }
.social-btn:hover { background: var(--accent); }
.social-btn svg { width: 16px; height: 16px; }
.footer-col h4 { font-size: .85rem; font-weight: 700; color: #fff; margin-bottom: 16px; letter-spacing: .02em; }
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col ul a { font-size: .84rem; transition: color var(--transition); }
.footer-col ul a:hover { color: #fff; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,.08); padding-top: 24px; display: flex; align-items: center; justify-content: space-between; flex-wrap: gap; font-size: .8rem; }
