}

/* ── Carousel Buttons ── */
function initCarousel() {
  const carousel = document.getElementById('trending-carousel');
  document.getElementById('carousel-prev')?.addEventListener('click', () => {
    carousel.scrollBy({ left: -(carousel.offsetWidth * 0.6), behavior: 'smooth' });
  });
  document.getElementById('carousel-next')?.addEventListener('click', () => {
    carousel.scrollBy({ left: carousel.offsetWidth * 0.6, behavior: 'smooth' });
  });
}

/* ── Category Filter ── */
function initCategories() {
  document.querySelectorAll('.cat-pill').forEach(pill => {
    pill.addEventListener('click', () => {
      document.querySelectorAll('.cat-pill').forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
    });
  });
}

/* ── Newsletter ── */
function initNewsletter() {
  document.getElementById('newsletter-form')?.addEventListener('submit', e => {
    e.preventDefault();
    const input = e.target.querySelector('input[type=email]');
    if (input?.value) {
      showToast('Thanks for subscribing! 🎉');
      input.value = '';
    }
  });
}

/* ── Nav Scroll Effect ── */
function initNavScroll() {
  const navbar = document.querySelector('.navbar');
  window.addEventListener('scroll', () => {
    navbar.style.boxShadow = window.scrollY > 20
      ? '0 2px 20px rgba(0,0,0,.08)'
      : 'none';
  }, { passive: true });
}

/* ── Mobile Menu ── */
function initMobileMenu() {
  const hamburger = document.querySelector('.hamburger');
  const navLinks  = document.querySelector('.nav-links');
  if (!hamburger || !navLinks) return;
  hamburger.addEventListener('click', () => {
    const open = navLinks.style.display === 'flex';
    navLinks.style.cssText = open
      ? ''
      : 'display:flex;flex-direction:column;position:absolute;top:64px;left:0;right:0;background:#fff;padding:16px 24px;border-bottom:1px solid var(--border);box-shadow:var(--shadow-md);z-index:99;gap:16px';
  });
}

/* ── Event Delegation ── */
function initEvents() {
  document.addEventListener('click', e => {
    const addBtn = e.target.closest('.add-to-cart');
    if (addBtn) { addToCart(Number(addBtn.dataset.id)); return; }

    const qtyBtn = e.target.closest('.qty-btn');
    if (qtyBtn) { changeQty(Number(qtyBtn.dataset.id), Number(qtyBtn.dataset.delta)); return; }

    const removeBtn = e.target.closest('.remove-btn');
    if (removeBtn) { removeFromCart(Number(removeBtn.dataset.id)); return; }

    const wishlistBtn = e.target.closest('.wishlist-btn');
    if (wishlistBtn) {
      wishlistBtn.style.color = wishlistBtn.style.color === 'var(--accent)' ? '' : 'var(--accent)';
      showToast(wishlistBtn.style.color ? 'Added to wishlist ♥' : 'Removed from wishlist');
      return;
    }

    const cartBtn = e.target.closest('#cart-btn');
    if (cartBtn) { openCart(); return; }

    const overlay = e.target.closest('#cart-overlay');
    if (overlay) { closeCart(); return; }

    const closeBtn = e.target.closest('#cart-close');
    if (closeBtn) { closeCart(); return; }
  });
}

/* ── Init ── */
document.addEventListener('DOMContentLoaded', () => {
  renderProducts();
  updateCart();
  initCountdown();
  initCarousel();
  initCategories();
  initNewsletter();
  initNavScroll();
  initMobileMenu();
  initEvents();
});
