  { id:10, brand:'Essentials', name:'Cloud Fleece Quarter-Zip', price:82, original:110, rating:4.7, reviews:290, badge:'sale', img:'https://images.unsplash.com/photo-1556821840-3a63f15732ce?w=480&q=80', color:'#ecdcd4' },
  { id:11, brand:'Lumé Studio', name:'Satin Slip Midi Skirt', price:95, original:null, rating:4.6, reviews:178, badge:'new', img:'https://images.unsplash.com/photo-1583496661160-fb5886a0aaaa?w=480&q=80', color:'#e4e0ec' },
  { id:12, brand:'Arken Co.', name:'Suede Chelsea Boots', price:178, original:240, rating:4.9, reviews:621, badge:'sale', img:'https://images.unsplash.com/photo-1543163521-1bf539c55dd2?w=480&q=80', color:'#e4d8cc' },
];

/* ── Cart State ── */
let cart = [];
let cartOpen = false;

/* ── Helpers ── */
function stars(rating) {
  const full  = Math.floor(rating);
  const half  = rating % 1 >= 0.5 ? 1 : 0;
  return '★'.repeat(full) + (half ? '½' : '') + '☆'.repeat(5 - full - half);
}

function discount(p, o) {
  if (!o) return '';
  return `<span class="badge badge-sale">-${Math.round((1 - p/o)*100)}%</span>`;
}

function renderProductCard(p) {
  const badgeMap = { sale:'badge-sale', new:'badge-new', hot:'badge-hot' };
  const badgeLabel = { sale:'Sale', new:'New', hot:'🔥 Hot' };
  return `
    <article class="product-card" data-id="${p.id}">
      <div class="product-img" style="background:${p.color}">
        <img src="${p.img}" alt="${p.name}" loading="lazy">
        <div class="product-badges">
          ${p.badge ? `<span class="badge ${badgeMap[p.badge]}">${badgeLabel[p.badge]}</span>` : ''}
        </div>
        <div class="product-actions">
          <button class="product-action-btn wishlist-btn" aria-label="Add to wishlist" title="Wishlist">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78L12 21.23l8.84-8.84a5.5 5.5 0 0 0 0-7.78z"/></svg>
          </button>
          <button class="product-action-btn quick-view-btn" aria-label="Quick view" title="Quick view">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
          </button>
        </div>
      </div>
      <div class="product-info">
        <p class="product-brand">${p.brand}</p>
        <h3 class="product-name">${p.name}</h3>
        <div class="product-rating">
          <span class="stars">${'★'.repeat(Math.floor(p.rating))}${'☆'.repeat(5-Math.floor(p.rating))}</span>
          <span class="rating-count">(${p.reviews})</span>
        </div>
        <div class="product-footer">
          <div class="product-price">
            <span class="price-current">$${p.price}</span>
            ${p.original ? `<span class="price-original">$${p.original}</span>` : ''}
          </div>
          <button class="add-to-cart" data-id="${p.id}" aria-label="Add to cart">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>
          </button>
        </div>
      </div>
    </article>`;
}

/* ── Render Grids ── */
function renderProducts() {
  document.getElementById('products-grid').innerHTML = PRODUCTS.map(renderProductCard).join('');
  document.getElementById('trending-carousel').innerHTML = TRENDING.map(renderProductCard).join('');
}

/* ── Cart Logic ── */
function addToCart(id) {
  const product = [...PRODUCTS, ...TRENDING].find(p => p.id === id);
  if (!product) return;
  const existing = cart.find(i => i.id === id);
  if (existing) {
    existing.qty++;
  } else {
    cart.push({ ...product, qty: 1 });
  }
  updateCart();
  showToast(`${product.name} added to cart`);
}

function removeFromCart(id) {
  cart = cart.filter(i => i.id !== id);
  updateCart();
}

function changeQty(id, delta) {
  const item = cart.find(i => i.id === id);
  if (!item) return;
  item.qty += delta;
  if (item.qty <= 0) removeFromCart(id);
  else updateCart();
}

function updateCart() {
  const total = cart.reduce((s, i) => s + i.qty, 0);
  const subtotal = cart.reduce((s, i) => s + i.price * i.qty, 0);

  document.querySelectorAll('.cart-count').forEach(el => {
    el.textContent = total;
    el.style.display = total > 0 ? 'flex' : 'none';
  });

  const itemsEl = document.getElementById('cart-items');
  const subtotalEl = document.getElementById('cart-subtotal');

  if (cart.length === 0) {
    itemsEl.innerHTML = `
      <div class="cart-empty">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>
        <p>Your cart is empty</p>
      </div>`;
  } else {
    itemsEl.innerHTML = cart.map(item => `
      <div class="cart-item">
        <div class="cart-item-img"><img src="${item.img}" alt="${item.name}" loading="lazy"></div>
        <div class="cart-item-info">
