    if (cartBtn) { openCart(); return; }

    const overlay = e.target.closest('#cart-overlay');
    if (overlay) { closeCart(); return; }

    const closeBtn = e.target.closest('#cart-close');
    if (closeBtn) { closeCart(); return; }
